parameters.jsonBody:
{
  "operationName": "searchJobsV3",
  "variables": {
    "data": {
      "SearchTerm": "data entry",
      "CountryCode": "ID",
      "LocationIds": ["0822446a-8784-4af4-bc88-9f9294fca382"],
      "includeExternalJobs": true,
      "sortBy": "LATEST",
      "pageSize": 30,
      "page": 1
    }
  },
  "query": "query searchJobsV3($data: JobSearchConditionInput!) {
  searchJobsV3(data: $data) {
    jobsInPage {
      id
      title
      workArrangementOption
      status
      createdAt
      updatedAt
      isHot
      isApplied
      shouldShowSalary
      educationLevel
      type
      fraudReportFlag
      company {
        ...CompanyFields
        __typename
      }
      citySubDivision {
        id
        name
        __typename
      }
      city {
        ...CityFields
        __typename
      }
      country {
        ...CountryFields
        __typename
      }
      salaries {
        ...SalaryFields
        __typename
      }
      location {
        ...LocationFields
        __typename
      }
      minYearsOfExperience
      maxYearsOfExperience
      source
      jobSource
      type
      hierarchicalJobCategory {
        id
        level
        name
        children {
          name
          level
          id
          __typename
        }
        parents {
          id
          level
          name
          __typename
        }
        __typename
      }
      skills {
        skill {
          id
          name
          __typename
        }
        mustHave
        __typename
      }
      traceInfo
      __typename
    }
    expInfo
    hasMore
    __typename
  }
}

fragment CompanyFields on Company {
  id
  name
  brandName
  logo
  status
  isVIP
  IndustryId
  industry {
    id
    name
    __typename
  }
  verificationTier {
    type
    userName
    __typename
  }
  __typename
}

fragment CityFields on City {
  id
  name
  __typename
}

fragment CountryFields on Country {
  code
  name
  __typename
}

fragment SalaryFields on JobSalary {
  id
  salaryType
  salaryMode
  maxAmount
  minAmount
  CurrencyCode
  __typename
}

fragment LocationFields on HierarchicalLocation {
  id
  name
  administrativeLevelName
  formattedName
  level
  slug
  latitude
  longitude
  parents {
    id
    name
    administrativeLevelName
    formattedName
    level
    slug
    CountryCode: countryCode
    parents {
      level
      formattedName
      slug
      __typename
    }
    __typename
  }
  __typename
}"
}

parameters.jsCode:
const jobs = $input.first().json.data.searchJobsV3.jobsInPage;

return jobs.map(job => ({
  json: {
    id: job.id,
    title: job.title,
    company: job.company?.name,
    companyVerified: job.company?.status,
    companyIsVIP: job.company?.isVIP,
    salary: job.salaries?.[0]
      ? `${job.salaries[0].minAmount || ''} - ${job.salaries[0].maxAmount || ''} ${job.salaries[0].CurrencyCode || ''}`
      : null,
    location: job.location?.name,
    latitude: job.location?.latitude,
    longitude: job.location?.longitude,
    createdAt: job.createdAt
  }
}));

const html = $input.item.json.data;

// Cari blok __NEXT_DATA__
const match = html.match(/<script id="__NEXT_DATA__" type="application\/json">(.*?)<\/script>/s);

if (!match) {
  return { json: { error: "NEXT_DATA tidak ditemukan" } };
}

let nextData;
try {
  nextData = JSON.parse(match[1]);
} catch (e) {
  return { json: { error: "Gagal parse NEXT_DATA: " + e.message } };
}

const job = nextData.props?.pageProps?.initialData?.data;

if (!job) {
  return { json: { error: "Struktur job tidak ditemukan" } };
}

// Bersihkan description dari draft-js JSON jadi teks polos
let description = '';
try {
  const descData = JSON.parse(job.descriptionJsonString || '{}');
  description = (descData.blocks || []).map(b => b.text).filter(t => t).join(' ');
} catch (e) {
  description = '';
}

// Parse social media
let socialMedia = {};
try {
  socialMedia = JSON.parse(job.company?.socialMediaSitesJsonString || '{}');
} catch (e) {}

const originalData = $('Code in JavaScript').item.json; // ganti sesuai nama node B lo

return {
  json: {
    id: job.id,
    title: job.title,
    company: job.company?.name,
    companyVerified: job.company?.status,
    companyIsVIP: job.company?.isVIP,
    industry: job.company?.industry?.name,
    companyAddress: job.company?.address,
    companyWebsite: job.company?.website,
    companyInstagram: socialMedia.instagram || null,
    companyLinkedin: socialMedia.linkedin || null,
    companyTwitter: socialMedia.twitter || null,
    companyFacebook: socialMedia.facebook || null,
    salary: job.salaries?.[0]
      ? `${job.salaries[0].minAmount} - ${job.salaries[0].maxAmount} ${job.salaries[0].CurrencyCode}`
      : null,
    description: description.trim(),
    datePosted: job.createdAt,
    location: job.location?.name,
    latitude: job.location?.latitude,
    longitude: job.location?.longitude,
    url: `https://glints.com/id/en/opportunities/jobs/job/${job.id}`
  }
};

function smartShorten(text, wordLimit) {
  if (!text) return '';

  // Ambil kalimat pertama (sampai titik pertama)
  const firstSentence = text.split(/(?<=[.!?])\s+/)[0];

  const words = firstSentence.split(/\s+/);
  if (words.length <= wordLimit) return firstSentence;

  return words.slice(0, wordLimit).join(' ') + '...';
}

return {
  json: {
    ...($input.item.json),
    shortDescription: smartShorten($input.item.json.description, 15)
  }
};

const html = $input.item.json.data;

// Cari semua job-card
const regex = /data-job-id="(\d+)"[^>]*aria-label="([^"]+)"/g;
const jobs = [];
let match;

while ((match = regex.exec(html)) !== null) {
  jobs.push({
    json: {
      id: match[1],
      title: match[2]
    }
  });
}

return jobs;

const html = $input.item.json.data;

// 1. Ambil blok window.SK_DL (data terstruktur)
const dlMatch = html.match(/window\.SK_DL\s*=\s*(\{.*?\});/s);
let salary = null, location = null, company = null, classification = null;

if (dlMatch) {
  try {
    const dl = JSON.parse(dlMatch[1]);
    salary = dl.jobSalary || null;
    location = dl.jobLocation || null;
    company = dl.advertiserName || null;
    classification = dl.jobClassification || null;
  } catch (e) {
    // biarin null kalau gagal parse
  }
}

// 2. Ambil description (tetap pakai cara sebelumnya)
const startIdx = html.indexOf('data-automation="jobAdDetails"');
let description = '';

if (startIdx !== -1) {
  const chunk = html.substring(startIdx, startIdx + 8000);
  const endMatch = chunk.match(/<\/section>|data-automation="(?!jobAdDetails)/);
  const trimmed = endMatch ? chunk.substring(0, endMatch.index) : chunk;
  description = trimmed
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const originalData = $('Code in JavaScript3').item.json; // sesuaikan nama node B lo

return {
  json: {
    id: originalData.id,
    title: originalData.title,
    company,
    salary,
    location,
    classification,
    description,
    source: 'jobstreet',
    url: `https://id.jobstreet.com/id/job/${originalData.id}`
  }
};

