const html = $input.first().json.data;

const regex = /jk=([a-f0-9]{16})/g;
const found = new Set();
let match;

while ((match = regex.exec(html)) !== null) {
  found.add(match[1]);
}

return Array.from(found).map(id => ({
  json: {
    id,
    source: 'indeed',
    url: `https://id.indeed.com/jobs?q=data+entry&l=surabaya&radius=25&sort=date&vjk=${id}`
  }
}));

const html = $input.item.json.data;

const marker = 'id="jobDescriptionText"';
const markerIdx = html.indexOf(marker);

let description = '';
if (markerIdx !== -1) {
  const afterMarker = html.indexOf('>', markerIdx) + 1;
  const chunk = html.substring(afterMarker, afterMarker + 8000);
  const endMatch = chunk.match(/<\/div>\s*<div[^>]*id="/);
  const trimmed = endMatch ? chunk.substring(0, endMatch.index) : chunk;
  description = trimmed
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Coba ambil title dari og:title (biasanya selalu ada di head)
const titleMatch = html.match(/property="og:title" content="([^"]+)"/);
const title = titleMatch ? titleMatch[1] : null;

// Coba ambil company dari meta atau structured data
const companyMatch = html.match(/"hiringOrganization"\s*:\s*\{[^}]*"name"\s*:\s*"([^"]+)"/);
const company = companyMatch ? companyMatch[1] : null;

// Coba ambil lokasi
const locationMatch = html.match(/"addressLocality"\s*:\s*"([^"]+)"/);
const location = locationMatch ? locationMatch[1] : null;

// Coba ambil salary
const salaryMatch = html.match(/"baseSalary"[\s\S]{0,200}?"value"\s*:\s*\{[^}]*"minValue"\s*:\s*(\d+)[^}]*"maxValue"\s*:\s*(\d+)/);
const salary = salaryMatch ? `${salaryMatch[1]} - ${salaryMatch[2]}` : null;

const originalData = $('Code in JavaScript6').item.json;

return {
  json: {
